:where(.keen) .symbol-group {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  margin-left: 10px;
}
:where(.keen) .symbol-group .symbol {
  position: relative;
  z-index: 0;
  margin-left: -10px;
  transition: all 0.3s ease;
}
:where(.keen) .symbol-group .symbol:hover {
  transition: all 0.3s ease;
  z-index: 1;
}
:where(.keen) .symbol-group .symbol-badge {
  border: 2px solid var(--bs-body-bg);
}
:where(.keen) .symbol-group .symbol-label {
  position: relative;
}
:where(.keen) .symbol-group .symbol-label:after {
  display: block;
  content: " ";
  border-radius: inherit;
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  bottom: 0;
  border: 2px solid var(--bs-symbol-border-color);
  -webkit-background-clip: padding-box; /* for Safari */
  background-clip: padding-box; /* for IE9+, Firefox 4+, Opera, Chrome */
}
:where(.keen) .symbol-group.symbol-hover .symbol {
  cursor: pointer;
}

:where(.keen) .pulse {
  position: relative;
}
:where(.keen) .pulse.pulse-light .pulse-ring {
  border-color: var(--bs-light);
}
:where(.keen) .pulse.pulse-primary .pulse-ring {
  border-color: var(--bs-primary);
}
:where(.keen) .pulse.pulse-secondary .pulse-ring {
  border-color: var(--bs-secondary);
}
:where(.keen) .pulse.pulse-success .pulse-ring {
  border-color: var(--bs-success);
}
:where(.keen) .pulse.pulse-info .pulse-ring {
  border-color: var(--bs-info);
}
:where(.keen) .pulse.pulse-warning .pulse-ring {
  border-color: var(--bs-warning);
}
:where(.keen) .pulse.pulse-danger .pulse-ring {
  border-color: var(--bs-danger);
}
:where(.keen) .pulse.pulse-dark .pulse-ring {
  border-color: var(--bs-dark);
}

:where(.keen) .pulse-ring {
  display: block;
  border-radius: 40px;
  height: 40px;
  width: 40px;
  position: absolute;
  animation: animation-pulse 3.5s ease-out;
  animation-iteration-count: infinite;
  opacity: 0;
  border-width: 3px;
  border-style: solid;
  border-color: var(--bs-gray-500);
}

@keyframes animation-pulse {
  0% {
    -webkit-transform: scale(0.1, 0.1);
    opacity: 0;
  }
  60% {
    -webkit-transform: scale(0.1, 0.1);
    opacity: 0;
  }
  65% {
    opacity: 1;
  }
  100% {
    -webkit-transform: scale(1.2, 1.2);
    opacity: 0;
  }
}
